import { Context } from '<tmp>'
const req = new Request('http://localhost/')
// A: #res exists with an old cookie; handler returns c.text with a new cookie in headers arg
let c = new Context(req)
c.header('set-cookie','old=1; Path=/',{append:true})
c.res // touch getter -> #res created sharing prepared headers
const res = c.text('hi', 200, { 'set-cookie': 'new=1; Path=/' })
console.log('A (c.res touched):', JSON.stringify(res.headers.getSetCookie()))
c.res = res
console.log('A after setter:', JSON.stringify(c.res.headers.getSetCookie()))
// B: same but getter not touched
c = new Context(req)
c.header('set-cookie','old=1; Path=/',{append:true})
const res2 = c.text('hi', 200, { 'set-cookie': 'new=1; Path=/' })
c.res = res2
console.log('B (getter untouched):', JSON.stringify(c.res.headers.getSetCookie()))
// C: incoming response built from old response; cookies duplicated?
c = new Context(req)
c.res = new Response('a')
c.res.headers.append('set-cookie','dup=1')
const derived = new Response('b', c.res)
